/* Pebble Radar - distribution, voice of the customer, regions, reports and strategy views.
   Loaded by index.html; uses its helpers ($, api, post, esc, fmt, inr, ago, pill, head, feedRow, spark, toast, STATS). */
(function(){
const X={};
/* a sector without a home brand (Nazar's neutral sectors) has no own store, sales or "you" column; those panels hide */
const NEUTRAL=()=>!(STATS&&STATS.self);const ME=()=>(STATS&&STATS.self)||"home brand";
/* app_metrics rows: Play packages are reverse-DNS ids, App Store rows carry an "ios:<id>" package (collectors/appstore.py) */
const appStore=a=>a.store||(/^ios:|^\d+$/.test(a.package||"")?"App Store":"Play");
const appUrl=a=>{const p=String(a.package||"");const m=p.match(/^(?:ios:)?(\d+)$/);return m?`https://apps.apple.com/in/app/id${m[1]}`:p?`https://play.google.com/store/apps/details?id=${encodeURIComponent(p)}`:"";};
const appLink=a=>{const u=appUrl(a);return u?`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(a.name||a.package||"")}</a>`:esc(a.name||"");};
window.appStore=appStore;window.appUrl=appUrl;window.appLink=appLink;
const inrS=n=>n==null?"–":Math.abs(n)>=1e7?"₹"+(n/1e7).toLocaleString("en-IN",{maximumFractionDigits:2})+" cr":Math.abs(n)>=1e5?"₹"+(n/1e5).toLocaleString("en-IN",{maximumFractionDigits:1})+" L":"₹"+fmt(n);
const pc=v=>v==null?"–":(v>0?"+":"")+Number(v).toFixed(v%1?1:0)+"%";
const col=v=>v>0?"var(--up)":v<0?"var(--s8)":"var(--muted)";
const chip=(t,c)=>`<span class="chip" style="${c?`border-color:${c};color:${c}`:""}">${esc(t)}</span>`;
const kpi=(l,v,s,c)=>`<div class="xk"><div class="l">${l}</div><div class="v num" style="${c?"color:"+c:""}">${v}</div>${s?`<div class="s">${s}</div>`:""}</div>`;
const tabs=(items,on,attr="data-x",cls="")=>`<div class="tabs${cls?" "+cls:""}">${items.map(([k,l])=>`<button class="${k===on?"on":""}" ${attr}="${esc(k)}">${esc(l)}</button>`).join("")}</div>`;
const bar=(label,v,mx,c,fv)=>`<div class="bar"><span title="${esc(label)}">${esc(String(label).slice(0,18))}</span><div class="tr"><div class="f" style="width:${mx?Math.min(100,v/mx*100):0}%;background:${c||"var(--s1)"}"></div></div><span class="v">${fv?fv(v):fmt(v)}</span></div>`;
function hbars(rows,o={}){const mx=o.max||Math.max(1,...rows.map(r=>r.v));return rows.map(r=>bar(r.l,r.v,mx,r.c,o.fv)).join("")||'<div class="empty">nothing yet</div>';}
const shortL=l=>{l=String(l);const w=l.match(/-W(\d+)$/);if(w)return"W"+w[1];if(/^\d{4}-\d{2}$/.test(l))return["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][+l.slice(5)-1];if(/^\d{4}-\d{2}-\d{2}$/.test(l))return l.slice(8);return l;};
function cols(series,o={}){const w=o.w||420,h=o.h||120,p=22;if(!series.length)return'<div class="empty">no data</div>';const mx=Math.max(1,...series.map(s=>s.v));const bw=Math.max(4,(w-2*p)/series.length-3);
  return`<svg viewBox="0 0 ${w} ${h}" width="100%" style="max-width:${w}px;display:block"><line x1="${p}" x2="${w-p/2}" y1="${h-18}" y2="${h-18}" stroke="var(--line)"/>${series.map((s,i)=>{const x=p+i*((w-2*p)/series.length),bh=(s.v/mx)*(h-34);return`<g data-tip="${esc(s.l)}: ${o.fv?o.fv(s.v):fmt(s.v)}${s.t?"\n"+esc(s.t):""}"><rect x="${x}" y="${h-18-bh}" width="${bw}" height="${bh}" rx="2" fill="${s.c||"var(--s1)"}"/>${series.length<=16?`<text x="${x+bw/2}" y="${h-5}" text-anchor="middle">${esc(shortL(s.l))}</text>`:""}</g>`;}).join("")}</svg>`;}
function line(vals,o={}){const w=o.w||380,h=o.h||70,p=6;if(!vals||vals.length<2)return'<span class="muted small">not enough points</span>';const mn=Math.min(...vals),mx=Math.max(...vals);const x=i=>p+i*(w-2*p)/(vals.length-1),y=v=>h-p-((v-mn)/(mx-mn||1))*(h-2*p);
  return`<svg viewBox="0 0 ${w} ${h}" width="100%" style="max-width:${w}px;display:block"><polyline points="${vals.map((v,i)=>`${x(i)},${y(v)}`).join(" ")}" fill="none" stroke="${o.color||"var(--s1)"}" stroke-width="2"/><circle cx="${x(vals.length-1)}" cy="${y(vals[vals.length-1])}" r="3" fill="${o.color||"var(--s1)"}"/></svg>`;}
/* a stylised India dot map: lat/lon projected on a plain canvas, sized by value */
function indiaMap(points,o={}){const W=o.w||520,H=o.h||560;const lon0=68,lon1=97.5,lat0=6.5,lat1=37;const X=lo=>(lo-lon0)/(lon1-lon0)*(W-40)+20,Y=la=>H-20-(la-lat0)/(lat1-lat0)*(H-40);
  const mx=Math.max(1,...points.map(p=>p.v||0));
  return`<svg viewBox="0 0 ${W} ${H}" width="100%" style="max-width:${W}px;display:block;margin:0 auto" role="img" aria-label="India map"><rect x="0" y="0" width="${W}" height="${H}" rx="12" fill="var(--surface-2)"/>${[8,16,24,32].map(la=>`<line x1="20" x2="${W-20}" y1="${Y(la)}" y2="${Y(la)}" stroke="var(--line)"/><text x="4" y="${Y(la)+3}">${la}°</text>`).join("")}${[72,80,88,96].map(lo=>`<line y1="20" y2="${H-20}" x1="${X(lo)}" x2="${X(lo)}" stroke="var(--line)"/>`).join("")}
  ${points.map(p=>{const r=p.v?4+Math.sqrt(p.v/mx)*18:3;return`<g data-tip="${esc(p.tip||p.l)}"${p.go?` style="cursor:pointer" data-go="${esc(p.go)}"`:""}><circle cx="${X(p.lon)}" cy="${Y(p.lat)}" r="${r}" fill="${p.c||"var(--s1)"}" fill-opacity=".55" stroke="${p.c||"var(--s1)"}"/>${p.label!==false&&(r>=9||p.always)?`<text x="${X(p.lon)+r+2}" y="${Y(p.lat)+4}" style="fill:var(--ink-2);font-size:11px">${esc(p.l)}</text>`:""}</g>`;}).join("")}</svg>`;}
const STATUS={live:["●","var(--good)","live listing"],reported:["○","var(--s4)","reported in news / press"],none:["·","var(--muted)","no sign"]};
const SRC={youtube:"YouTube",appstore:"App Store",play:"Google Play",amazon:"Amazon",judgeme:"Own store"};
const md=s=>{let h=esc(s);h=h.replace(/^### (.*)$/gm,"<h3>$1</h3>").replace(/^## (.*)$/gm,"<h2>$1</h2>").replace(/^# (.*)$/gm,"<h1 style='font-size:18px'>$1</h1>").replace(/\*\*(.+?)\*\*/g,"<b>$1</b>").replace(/_(.+?)_/g,"<i>$1</i>").replace(/^---$/gm,"<hr>");
  h=h.replace(/((?:^\|.*\|\s*$\n?)+)/gm,t=>{const rows=t.trim().split("\n").filter(r=>!/^\|[-| ]+\|$/.test(r));return"<table>"+rows.map((r,i)=>"<tr>"+r.replace(/^\||\|$/g,"").split("|").map(c=>`<${i?"td":"th"}>${c.trim()}</${i?"td":"th"}>`).join("")+"</tr>").join("")+"</table>";});
  h=h.replace(/((?:^- .*$\n?)+)/gm,t=>"<ul>"+t.trim().split("\n").map(l=>"<li>"+l.slice(2)+"</li>").join("")+"</ul>");return h.replace(/\n{2,}/g,"<br>").replace(/\n/g," ");};

/* ---------- Channels ---------- */
X.vChannels=async function(v){const name=param();if(name)return chBrand(v,name);head("Channels","where every brand is actually sold: marketplaces, quick commerce per city, retail and the app stores");
  const [m,pi,qc,apps]=await Promise.all([api("/api/channels"),api("/api/channels/price_index"),api("/api/channels/qc"),api("/api/app_health").catch(()=>[])]);const anyListing=(m.stats.listings||0)>0;const und=anyListing?await api("/api/channels/parity"):[];
  const peb=m.brands.find(b=>b.self);const live=k=>m.brands.filter(b=>b.cells[k].status==="live").length,rep=k=>m.brands.filter(b=>b.cells[k].status==="reported").length;
  const before=`<div class="xkpis">${kpi("listings tracked",fmt(m.stats.listings),"Amazon.in · Flipkart · Blinkit")}${kpi("brands live on a shelf",m.stats.live_brands,`of ${m.brands.length}`)}${peb?kpi(`${esc(ME())} channels`,peb.channels_present,`${peb.qc_cities} Blinkit cities`):kpi("apps tracked",apps.length,"Play and App Store")}${kpi("undercuts of own-store prices",und.length,"last 45 days",und.some(u=>u.self)?"var(--s8)":"")}</div>`;
  const matrix_=anyListing?`<div class="card"><h2>Distribution matrix <span class="hint">● live listing · ○ reported in news / press · number = Blinkit cities · click a brand</span></h2><div style="overflow-x:auto"><table class="xmat"><tr><th>Brand</th>${m.channels.map(c=>`<th title="${esc(c.type)} · ${esc(c.reader)}">${esc(c.name.split(" /")[0].slice(0,14))}<div class="small muted" style="font-weight:400;text-transform:none;letter-spacing:0">${live(c.key)}● ${rep(c.key)}○</div></th>`).join("")}<th class="num">Present</th></tr>
    ${m.brands.map(b=>`<tr style="${b.self?"background:color-mix(in srgb,var(--accent) 8%,transparent)":""}"><td><a href="#/channels/${encodeURIComponent(b.brand)}">${esc(b.brand)}</a>${b.self?' <span class="pill i0">you</span>':""}</td>${m.channels.map(c=>{const x=b.cells[c.key],s=STATUS[x.status];const tip=x.status==="live"?`${x.listings} listings, ${x.in_stock} in stock${x.min_price?`, from ₹${fmt(x.min_price)}`:""}${x.rating?`, rating ${x.rating} (${fmt(x.rating_count)})`:""}${x.cities.length?`\n${x.cities.join(", ")}`:""}`:x.status==="reported"?`${x.mentions} mention${x.mentions>1?"s":""}, last ${x.last_mention}\n${x.mention_title}`:"no listing or mention found";return`<td class="c" data-tip="${esc(tip)}" style="color:${s[1]}">${s[0]}${x.cities.length?`<sub>${x.cities.length}</sub>`:""}${x.status==="live"&&x.min_price?`<div class="small muted">₹${fmt(x.min_price)}</div>`:""}</td>`;}).join("")}<td class="num">${b.channels_present}</td></tr>`).join("")}</table></div></div>`
    :`<div class="empty">No marketplace or quick-commerce listing in this sector yet. ${NEUTRAL()?"App stores are the shelf here: see the App stores tab.":"Amazon.in and Flipkart are read every 6 hours, Blinkit daily (config/channels.yaml)."}</div>`;
  const prices_=`<div class="grid g2"><div class="card"><h2>Price parity <span class="hint">marketplace below the brand's own store</span></h2>${und.length?`<table><tr><th>Brand</th><th>Product</th><th class="num">Marketplace</th><th class="num">Own store</th><th class="num">Gap</th></tr>${und.slice(0,14).map(u=>`<tr><td>${esc(u.brand)}</td><td><a href="${esc(u.url)}" target="_blank" rel="noopener">${esc(u.title.replace(/^.*? sells /,"").slice(0,70))}</a><div class="small muted">${esc(u.channel)} · ${u.when}</div></td><td class="num">${inr(u.marketplace_price)}</td><td class="num">${inr(u.store_price)}</td><td class="num" style="color:var(--s8)">-${u.gap_pct}%</td></tr>`).join("")}</table>`:'<div class="empty">No marketplace listing undercuts an own-store price yet.</div>'}</div>
    <div class="card"><h2>Discount depth <span class="hint">marketplace price vs MRP, 30 days</span></h2>${pi.length?hbars(pi.slice(0,14).map(p=>({l:p.brand,v:p.avg_discount_pct,c:p.self?"var(--accent)":"var(--s2)"})),{fv:v=>v+"%",max:100}):'<div class="empty">Waiting for the first marketplace sweep.</div>'}</div></div>`;
  const qc_=`<div class="card"><h2>Quick commerce by city <span class="hint">Blinkit shelves · brands with at least one live SKU · daily</span></h2>${qc.cities.some(c=>c.brand_count)?`<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(210px,1fr))">${qc.cities.map(c=>`<div style="padding:8px 0;border-bottom:1px solid var(--line)"><div class="row"><b>${esc(c.city)}</b><span class="muted small">${esc(c.state)}</span><span class="grow"></span><span class="num">${c.brand_count} brands</span></div><div class="small">${Object.entries(c.brands).sort((a,b)=>b[1].in_stock-a[1].in_stock).slice(0,8).map(([b,x])=>chip(`${b} ${x.in_stock}`,b===STATS.self?"var(--accent)":"")).join("")||'<span class="muted">no tracked brand on the shelf</span>'}</div></div>`).join("")}</div>`:'<div class="empty">Blinkit shelves are read with the daily tier (config/channels.yaml lists the cities).</div>'}</div>`;
  const apps_=`<div class="card"><h2>${NEUTRAL()?"App stores are the shelf in this sector":"App stores"} <span class="hint">Google Play and App Store · rating, ratings, installs</span></h2>${apps.length?`<table><tr><th>Brand</th><th>App</th><th>Store</th><th class="num">Rating</th><th class="num">Ratings</th><th class="num">Installs</th><th>Updated</th></tr>${apps.map(a=>`<tr><td><a href="#/brand/${encodeURIComponent(a.brand)}">${esc(a.brand)}</a></td><td>${appLink(a)}</td><td class="small muted">${esc(appStore(a))}</td><td class="num">${a.rating??"–"} ${a.rating_delta?`<span class="small" style="color:${col(a.rating_delta)}">${pc(a.rating_delta)}</span>`:""}</td><td class="num">${fmt(a.ratings_count)}${a.ratings_gained?` <span class="small muted">+${fmt(a.ratings_gained)}</span>`:""}</td><td class="num">${esc(a.downloads||"–")}</td><td class="small muted">${esc(a.updated_on||"")}</td></tr>`).join("")}</table>`:'<div class="empty">No companion app on file yet. App ids are resolved and read in the daily tier.</div>'}</div>`;
  const tabs_=[{key:"matrix",label:"Distribution matrix",html:matrix_},{key:"prices",label:"Prices & parity",html:prices_,count:und.length||null},{key:"qc",label:"Quick commerce",html:qc_},{key:"apps",label:"App stores",html:apps_,count:apps.length||null}];
  if(NEUTRAL()&&!anyListing)tabs_.unshift(tabs_.pop());
  tabbed(v,tabs_,{before});};
async function chBrand(v,name){const d=await api("/api/channels/"+encodeURIComponent(name));head(name+" · channels",`<a href="#/channels">← distribution matrix</a> · <a href="#/brand/${encodeURIComponent(name)}">brand page</a>`);
  v.innerHTML=`<div class="grid" style="grid-template-columns:1fr">${d.channels.map(ch=>`<div class="card"><h2>${esc(ch.name)} <span class="hint">${ch.listings.length} listings</span></h2><table><tr><th>Product</th>${ch.type==="quick_commerce"?"<th>City</th>":""}<th class="num">Price</th><th class="num">MRP</th><th>Stock</th><th class="num">Rating</th><th>Trail</th></tr>${ch.listings.slice(0,60).map(l=>`<tr><td><a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.title.slice(0,70))}</a>${l.sponsored?' <span class="chip">sponsored</span>':""}<div class="small muted">#${l.position||"–"} for "${esc(l.query)}" · since ${l.first_seen.slice(0,10)}</div></td>${ch.type==="quick_commerce"?`<td>${esc(l.city)}</td>`:""}<td class="num">${inr(l.price)}${l.first_price&&l.first_price!==l.price?` <span class="small" style="color:${col(l.first_price-l.price)}">${pc(100*(l.price-l.first_price)/l.first_price)}</span>`:""}</td><td class="num muted">${inr(l.mrp)}</td><td>${l.available?"✓":'<span style="color:var(--s8)">out</span>'}</td><td class="num">${l.rating?`${l.rating} <span class="small muted">(${fmt(l.rating_count)})</span>`:"–"}</td><td>${line(l.history.filter(h=>h.price).map(h=>h.price),{w:120,h:28})}</td></tr>`).join("")}</table></div>`).join("")||'<div class="card"><div class="empty">No live listing yet for this brand.</div></div>'}
   <div class="grid g2"><div class="card"><h2>Reported presence <span class="hint">news, press, social</span></h2>${d.mentions.length?d.mentions.map(m=>`<div class="small" style="padding:5px 0;border-bottom:1px solid var(--line)">${chip(m.channel)} <a href="${esc(m.url)}" target="_blank" rel="noopener">${esc(m.title)}</a> <span class="muted">${m.seen_at.slice(0,10)}</span></div>`).join(""):'<div class="empty">No channel named next to this brand yet.</div>'}</div>
   <div class="card"><h2>Channel events</h2>${d.events.map(e=>`<div class="small" style="padding:5px 0;border-bottom:1px solid var(--line)">${pill(e.importance)} ${esc(kind(e.kind))} · <a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.title)}</a> <span class="muted">${ago(e.created_at)}</span></div>`).join("")||'<div class="empty">Nothing yet.</div>'}</div></div></div>`;}

/* ---------- Reviews (voice of the customer): the market, the demand, every brand, every item ---------- */
const stackBar=(pos,neg,n,w)=>{const p=n?pos/n*100:0,g=n?neg/n*100:0;return`<div class="tr" style="position:relative"><div style="position:absolute;left:0;top:0;bottom:0;width:${p.toFixed(1)}%;background:var(--good);border-radius:3px 0 0 3px"></div><div style="position:absolute;left:${p.toFixed(1)}%;top:0;bottom:0;width:${g.toFixed(1)}%;background:var(--s8);border-radius:0 3px 3px 0"></div></div>`;};
const star=v=>v==null?'<span class="muted">–</span>':`<b style="color:${v>=4.2?"var(--good)":v<3.5?"var(--s8)":"inherit"}">${Number(v).toFixed(2)}</b>`;
const READ={"table stakes":"var(--good)","open wound":"var(--s8)","contested":"var(--s4)","thin data":"var(--muted)"};
X.vVoice=async function(v){const F=JSON.parse(sessionStorage.getItem("voicef")||"{}");const days=F.days||90;head("Reviews","what buyers say and want: market read, demand themes, ratings scoreboard, every brand, every comment");
  const [s,mx,m]=await Promise.all([api(`/api/voice?days=${days}`),api(`/api/voice/matrix?days=${days}`),api(`/api/voice/market?days=${days}`)]);const peb=s.brands.find(b=>b.self);
  const tr=m.trend||[];const mxw=Math.max(1,...tr.map(t=>t.items));
  const before=`<div class="xkpis">${kpi("items read",fmt(s.stats.items),`${s.stats.brands} brands · ${days} days`)}${kpi("field negative share",s.stats.neg_pct_field+"%",`avg rating ${s.stats.avg_rating_field||"–"}`)}${NEUTRAL()?"":kpi("Pebble negative share",peb?peb.neg_pct+"%":"–",peb?`${peb.items} items · avg ${peb.avg_rating||"–"}`:"no Pebble items yet",peb&&peb.neg_pct>s.stats.neg_pct_field?"var(--s8)":"var(--up)")}${kpi("sources",(m.by_source||[]).length,(m.by_source||[]).map(x=>`${SRC[x.source]||x.source} ${fmt(x.items)}`).join(" · ")||"none yet")}<div class="xk"><div class="l">window</div><div class="row">${[30,90,180].map(d=>`<button class="sm ${d===days?"primary":""}" data-days="${d}">${d}d</button>`).join("")}</div><div class="s" style="margin-top:6px"><button class="sm ghost" id="vref" title="Read App Store, Google Play, YouTube comments, Amazon.in and own-store reviews now">↻ refresh reviews</button> ${m.last_run&&m.last_run.at?lastRunLine(m.last_run):""}</div></div></div>`;
  const overview_=`<div class="card" style="border-color:var(--accent)"><h2>Market read <span class="hint">what Indian buyers say across every brand · ${days} days</span></h2><div class="ink2" style="line-height:1.55">${esc(m.conclusion||"")}</div>
    <div class="row" style="margin-top:8px">${STATS.ai?`<button class="sm ghost" id="vmd">AI read of the field</button>`:'<span class="small muted">add GEMINI_API_KEY or ANTHROPIC_API_KEY for an AI-written read</span>'}</div><div class="answer small" id="vmdout"></div></div>
   <div class="grid g3" style="margin-top:16px">
    <div class="card"><h2>What buyers talk about <span class="hint">theme · praise vs complaints</span></h2>${(m.demand||[]).slice(0,13).map(d=>`<div class="bar" data-tip="${esc(d.read)} · ${d.pos} praise · ${d.neg} complaints · ${d.brands} brands"><span>${esc(d.theme)}</span>${stackBar(d.pos,d.neg,d.n,0)}<span class="v">${d.n}</span></div>`).join("")||'<div class="empty">No items yet.</div>'}<div class="legend" style="margin-top:8px"><span><i style="background:var(--good)"></i>praise</span><span><i style="background:var(--s8)"></i>complaints</span></div>
     <div style="margin-top:8px">${(m.demand||[]).filter(d=>d.n>=10).slice(0,8).map(d=>`<div class="small" style="padding:3px 0"><span class="chip" style="border-color:${READ[d.read.split(":")[0]]||"var(--line)"};color:${READ[d.read.split(":")[0]]||"inherit"}">${esc(d.theme)}</span> ${esc(d.read)}</div>`).join("")}</div></div>
    <div class="card"><h2>What India asks for <span class="hint">Google autocomplete, grouped into feature asks</span></h2>${(m.asks||[]).length?hbars((m.asks||[]).slice(0,12).map(a=>({l:a.ask,v:a.n,c:a.new_30d?"var(--s3)":"var(--s1)"})))+`<div class="small muted" style="margin-top:8px">${(m.asks||[]).slice(0,5).map(a=>`<div style="padding:2px 0"><b>${esc(a.ask)}</b>: ${a.examples.map(esc).join(" · ")}${a.brands.length?` <span class="muted">· ${a.brands.map(esc).join(", ")}</span>`:""}</div>`).join("")}</div>`:'<div class="empty">The search-demand sensor has not stored suggestions yet.</div>'}</div>
    <div class="card"><h2>Mood by week <span class="hint">items · negative share · Pebble</span></h2>${tr.some(t=>t.items)?`<div style="display:flex;align-items:flex-end;gap:4px;height:90px">${tr.map(t=>`<div data-tip="${t.week}: ${t.items} items, ${t.neg_pct==null?"–":t.neg_pct+"%"} negative, Pebble ${t.pebble}" style="flex:1;display:flex;flex-direction:column;justify-content:flex-end;height:100%"><div style="height:${(t.items/mxw*100).toFixed(0)}%;background:linear-gradient(to top,var(--s8) ${t.neg_pct||0}%,var(--s1) ${t.neg_pct||0}%);border-radius:3px 3px 0 0;min-height:2px"></div></div>`).join("")}</div><div class="row small muted" style="margin-top:4px"><span>${tr[0].week}</span><span class="grow"></span><span>${tr[tr.length-1].week}</span></div><div class="legend"><span><i style="background:var(--s8)"></i>negative part</span><span><i style="background:var(--s1)"></i>rest</span></div>`:'<div class="empty">No dated items yet.</div>'}
     <h2 style="margin-top:12px">By segment</h2><table><tr><th>Segment</th><th class="num">Items</th><th class="num">Rating</th><th class="num">Neg</th><th>Top complaint</th><th>Top praise</th></tr>${(m.by_segment||[]).map(g=>`<tr><td>${esc(g.name)}</td><td class="num">${g.items}</td><td class="num">${star(g.avg_rating)}</td><td class="num" style="color:${g.neg_pct>=30?"var(--s8)":"inherit"}">${g.neg_pct}%</td><td>${g.top_complaint?chip(g.top_complaint,"var(--s8)"):"–"}</td><td>${g.top_praise?chip(g.top_praise,"var(--good)"):"–"}</td></tr>`).join("")||'<tr><td colspan=6 class="muted">nothing yet</td></tr>'}</table></div>
   </div>
`;
  const score_=`<div class="card"><h2>Ratings scoreboard <span class="hint">every public rating per brand · composite = mean of the stores · click a brand</span></h2><div style="overflow-x:auto"><table><tr><th>Brand</th><th class="num">Composite</th><th class="num">Google Play</th><th class="num">App Store</th><th class="num">Own store</th><th class="num">Amazon.in</th><th class="num">Comments read</th><th class="num">Negative</th><th>Complaints</th><th>Praise</th></tr>${(m.scoreboard||[]).map(r=>`<tr style="cursor:pointer${r.self?";background:color-mix(in srgb,var(--accent) 8%,transparent)":""}" data-vb="${esc(r.brand)}" data-vt=""><td><b>${esc(r.brand)}</b>${r.self?' <span class="pill i0">you</span>':""}</td><td class="num">${star(r.composite)}</td><td class="num">${star(r.play)}${r.play_count?`<div class="small muted">${fmt(r.play_count)}</div>`:""}</td><td class="num">${star(r.ios)}${r.ios_count?`<div class="small muted">${fmt(r.ios_count)}</div>`:""}</td><td class="num">${star(r.store)}${r.store_count?`<div class="small muted">${fmt(r.store_count)}</div>`:""}</td><td class="num">${star(r.amazon)}${r.amazon_count?`<div class="small muted">${fmt(r.amazon_count)}</div>`:""}</td><td class="num">${r.voice_items||"–"}</td><td class="num" style="color:${r.neg_pct>=30?"var(--s8)":"inherit"}">${r.neg_pct==null?"–":r.neg_pct+"%"}</td><td>${r.top_complaints.slice(0,3).map(t=>chip(t,"var(--s8)")).join("")||"–"}</td><td>${r.top_praise.slice(0,3).map(t=>chip(t,"var(--good)")).join("")||"–"}</td></tr>`).join("")||'<tr><td colspan=10 class="muted">No ratings yet.</td></tr>'}</table></div></div>
   <div class="card" style="margin-top:16px"><h2>Who hears what <span class="hint">share of each brand's items that complain about a theme · darker = more complaints · click a cell</span></h2><div style="overflow-x:auto"><table class="xmat"><tr><th>Brand</th><th class="num">Items</th><th class="num">Rating</th>${mx.themes.map(t=>`<th>${esc(t)}</th>`).join("")}</tr>${mx.brands.map(b=>{const sb=s.brands.find(x=>x.brand===b.brand)||{};return`<tr style="${b.self?"background:color-mix(in srgb,var(--accent) 8%,transparent)":""}"><td><b>${esc(b.brand)}</b></td><td class="num">${b.items}</td><td class="num">${sb.avg_rating||"–"}</td>${mx.themes.map(t=>{const c=b.cells[t];const a=Math.min(1,c.neg_pct/25);return`<td class="c" data-vb="${esc(b.brand)}" data-vt="${t}" style="cursor:pointer;background:rgba(227,73,72,${(a*0.75).toFixed(2)});color:${a>0.5?"#fff":"inherit"}" data-tip="${esc(b.brand)} · ${t}\n${c.neg} complaints · ${c.pos} praise · ${c.n} mentions">${c.neg||""}${c.pos?`<sub>+${c.pos}</sub>`:""}</td>`;}).join("")}</tr>`;}).join("")||`<tr><td colspan=${mx.themes.length+3} class="muted">No items yet.</td></tr>`}</table></div></div>
`;
  const brands_=`<h2 style="margin:0 0 10px">Every brand <span class="hint muted small" style="font-weight:400">conclusion, quotes, trend</span></h2>
   <div class="grid g2">${s.brands.map(b=>`<div class="card"><h2>${esc(b.brand)}${b.self?' <span class="pill i0">you</span>':""} <span class="hint">${b.items} items · ${Object.entries(b.sources).map(([k,n])=>`${SRC[k]||k} ${n}`).join(" · ")}</span></h2>
     <div class="row wrap small" style="margin-bottom:8px"><span>rating <b>${b.avg_rating||"–"}</b></span><span>negative <b style="color:${b.neg_pct>=30?"var(--s8)":"inherit"}">${b.neg_pct}%</b></span><span>complaints: ${b.top_complaints.map(t=>chip(t,"var(--s8)")).join("")||"–"}</span><span>praise: ${b.top_praise.map(t=>chip(t,"var(--good)")).join("")||"–"}</span></div>
     <div class="small ink2" style="line-height:1.5;margin-bottom:8px">${esc(b.conclusion||"")}</div>
     ${(b.quotes.neg.slice(0,2).map(q=>`<div class="xq neg">“${esc(q.text)}” <span class="muted">— ${SRC[q.source]||q.source}${q.likes?` · ${fmt(q.likes)} likes`:""} · ${q.created}${q.url?` · <a href="${esc(q.url)}" target="_blank" rel="noopener">open</a>`:""}</span></div>`).join(""))}${(b.quotes.pos.slice(0,1).map(q=>`<div class="xq pos">“${esc(q.text)}” <span class="muted">— ${SRC[q.source]||q.source} · ${q.created}</span></div>`).join(""))}
     <div class="row" style="margin-top:8px"><button class="sm ghost" data-vb="${esc(b.brand)}" data-vt="">all items</button><a class="small" href="#/brand/${encodeURIComponent(b.brand)}">brand page →</a>${STATS.ai?`<button class="sm ghost" data-dig="${esc(b.brand)}">AI read</button>`:""}</div><div class="answer small" id="dig-${esc(b.brand).replace(/\W/g,"_")}"></div></div>`).join("")||'<div class="card"><div class="empty">No comments or reviews collected yet. Press “refresh reviews” above: the collector reads App Store and Google Play reviews of every companion app, YouTube comments under each brand\'s videos, Amazon.in product pages and the brands\' own store reviews.</div></div>'}</div>
`;
  const explore_=`<div class="card" id="vitems"><h2>Explore every item <span class="hint">filters apply to the ${days}-day window</span></h2><div class="row wrap" style="margin-bottom:8px"><select id="vfb"><option value="">All brands</option>${s.brands.map(b=>`<option>${esc(b.brand)}</option>`).join("")}</select><select id="vfs"><option value="">All sources</option>${(m.by_source||[]).map(x=>`<option value="${esc(x.source)}">${SRC[x.source]||x.source}</option>`).join("")}</select><select id="vft"><option value="">All themes</option>${mx.themes.map(t=>`<option>${t}</option>`).join("")}</select><select id="vfp"><option value="">Praise and complaints</option><option value="neg">Complaints only</option><option value="pos">Praise only</option></select><input id="vfq" placeholder="search text…" style="min-width:160px"><button class="sm" id="vgo">Show</button></div><div id="vlist" class="small muted">Pick a brand on the Scoreboard tab, a theme cell, or filter here.</div></div>`;
  tabbed(v,[{key:"overview",label:"Overview",html:overview_},{key:"scoreboard",label:"Scoreboard & themes",html:score_},{key:"brands",label:"Every brand",html:brands_,count:s.brands.length},{key:"explore",label:"Explore items",html:explore_}],{before});
  v.querySelectorAll("[data-days]").forEach(b=>b.onclick=()=>{sessionStorage.setItem("voicef",JSON.stringify({days:+b.dataset.days}));render();});
  const show=async(brand,theme,source,pol,q)=>{const rows=await api(`/api/voice/items?brand=${encodeURIComponent(brand||"")}&theme=${encodeURIComponent(theme||"")}&source=${encodeURIComponent(source||"")}&polarity=${pol||""}&q=${encodeURIComponent(q||"")}&days=${days}&limit=120`,{});
    $("#vlist").className="";$("#vlist").innerHTML=`<div class="small muted" style="margin-bottom:6px">${rows.length} items, newest first${brand?` · ${esc(brand)}`:""}${theme?` · ${esc(theme)}`:""}</div>`+(rows.map(r=>`<div class="xq ${r.sentiment<=-0.3?"neg":r.sentiment>=0.3?"pos":""}">${r.rating?`<b>${r.rating}★</b> `:""}${esc(r.text)} <span class="muted">— <b>${esc(r.brand)}</b> · ${SRC[r.source]||r.source} · ${esc(r.ref_title||"").slice(0,50)} · ${r.created}${r.url?` · <a href="${esc(r.url)}" target="_blank" rel="noopener">open</a>`:""}</span> ${r.themes.map(t=>chip(t)).join("")}</div>`).join("")||'<div class="empty">Nothing matches.</div>');showTab("explore");$("#vitems").scrollIntoView({behavior:"smooth",block:"start"});};
  v.querySelectorAll("[data-vb]").forEach(el=>el.onclick=()=>{$("#vfb").value=el.dataset.vb;$("#vft").value=el.dataset.vt||"";show(el.dataset.vb,el.dataset.vt,"","","");});
  $("#vgo").onclick=()=>show($("#vfb").value,$("#vft").value,$("#vfs").value,$("#vfp").value,$("#vfq").value);$("#vfq").onkeydown=e=>{if(e.key==="Enter")$("#vgo").click();};
  $("#vref").onclick=()=>collectNow("voice",$("#vref"));
  const md=$("#vmd");if(md)md.onclick=async()=>{const o=$("#vmdout");o.textContent="Reading the field…";try{const r=await post(`/api/voice/market_digest?days=${days}`);o.textContent=r.text||r.message||"No answer.";}catch(e){o.textContent="Failed: "+e.message;}};
  v.querySelectorAll("[data-dig]").forEach(b=>b.onclick=async()=>{const host=$("#dig-"+b.dataset.dig.replace(/\W/g,"_"));host.textContent="Reading…";const r=await post(`/api/voice/digest?brand=${encodeURIComponent(b.dataset.dig)}&days=${days}`);host.textContent=r.text||r.message||"No AI key configured.";});};
/* brand page: Reviews tab (called from index.html with the brand payload) */
X.brandReviews=function(d){const v=d.voice;if(!v||!v.summary)return`<div class="card"><div class="empty">No comments or reviews for ${esc(d.brand)} yet. The daily voice run reads its App Store and Play reviews, YouTube comments and Amazon.in listings; <a href="#/voice">Reviews page →</a></div></div>`;
  const b=v.summary,r=v.scoreboard||{},tl=v.timeline||[];const mxw=Math.max(1,...tl.map(t=>t.items));
  return`<div class="grid g2"><div class="card"><h2>What buyers say <span class="hint">${b.items} items · ${v.days} days</span></h2><div class="ink2" style="line-height:1.55;margin-bottom:10px">${esc(v.conclusion||"")}</div>${v.digest?`<div class="answer small" style="margin-bottom:10px">${esc(v.digest)}</div>`:""}
    <div class="row wrap small" style="margin-bottom:8px"><span>complaints: ${b.top_complaints.map(t=>chip(t,"var(--s8)")).join("")||"–"}</span><span>praise: ${b.top_praise.map(t=>chip(t,"var(--good)")).join("")||"–"}</span></div>
    ${b.quotes.neg.slice(0,3).map(q=>`<div class="xq neg">“${esc(q.text)}” <span class="muted">— ${SRC[q.source]||q.source} · ${q.created}${q.url?` · <a href="${esc(q.url)}" target="_blank" rel="noopener">open</a>`:""}</span></div>`).join("")}${b.quotes.pos.slice(0,2).map(q=>`<div class="xq pos">“${esc(q.text)}” <span class="muted">— ${SRC[q.source]||q.source} · ${q.created}</span></div>`).join("")}
    <a class="small" href="#/voice">compare with the field on the Reviews page →</a></div>
   <div style="display:grid;gap:16px;align-content:start"><div class="card"><h2>Ratings</h2><table><tr><th>Where</th><th class="num">Rating</th><th class="num">Count</th></tr><tr><td>Google Play</td><td class="num">${star(r.play)}</td><td class="num">${fmt(r.play_count||0)}</td></tr><tr><td>App Store</td><td class="num">${star(r.ios)}</td><td class="num">${fmt(r.ios_count||0)}</td></tr><tr><td>Own store</td><td class="num">${star(r.store)}</td><td class="num">${fmt(r.store_count||0)}</td></tr><tr><td>Amazon.in</td><td class="num">${star(r.amazon)}</td><td class="num">${fmt(r.amazon_count||0)}</td></tr><tr><td><b>Composite</b></td><td class="num">${star(r.composite)}</td><td class="num muted small">${b.neg_pct}% negative · field ${v.field_neg_pct}%</td></tr></table></div>
    <div class="card"><h2>Mood by week</h2>${tl.length?`<div style="display:flex;align-items:flex-end;gap:4px;height:70px">${tl.map(t=>`<div data-tip="${t.week}: ${t.items} items, ${t.neg} negative" style="flex:1;display:flex;flex-direction:column;justify-content:flex-end;height:100%"><div style="height:${(t.items/mxw*100).toFixed(0)}%;background:linear-gradient(to top,var(--s8) ${t.items?Math.round(100*t.neg/t.items):0}%,var(--s1) ${t.items?Math.round(100*t.neg/t.items):0}%);border-radius:3px 3px 0 0;min-height:2px"></div></div>`).join("")}</div>`:'<div class="empty">Not enough dated items.</div>'}</div>
    <div class="card"><h2>Themes</h2>${Object.entries(b.themes).slice(0,10).map(([t,c])=>`<div class="bar"><span>${esc(t)}</span>${stackBar(c.pos,c.neg,c.n,0)}<span class="v">${c.n}</span></div>`).join("")||'<div class="empty">none</div>'}</div></div></div>`;};

/* ---------- Regions ---------- */
X.vRegions=async function(v){head("Regions",NEUTRAL()?"where demand is: search interest by state and quick-commerce shelves":"where demand is: search interest by state, own sales by state and city, quick-commerce shelves");const d=await api("/api/regions");const me=STATS.self||"";const N=NEUTRAL();
  const F=JSON.parse(sessionStorage.getItem("regf")||"{}");const mode=F.mode||(d.sales.total_revenue?"sales":"interest");const brands=d.brands.map(b=>b.brand);const bsel=F.brand||me;
  const pts=mode==="sales"?d.states.filter(s=>s.sales_revenue).map(s=>({l:s.state,lat:s.lat,lon:s.lon,v:s.sales_revenue,c:"var(--accent)",tip:`${s.state}\n${inrS(s.sales_revenue)} · ${fmt(s.sales_units)} units · ${s.sales_orders} orders · ${s.sales_share_pct}% of sales`}))
    :mode==="qc"?d.cities.filter(c=>c.qc_brands).map(c=>({l:c.city,lat:c.lat,lon:c.lon,v:c.qc_brands,always:true,c:c.qc_pebble?"var(--accent)":"var(--s2)",tip:`${c.city}: ${c.qc_brands} brands on Blinkit${c.qc_pebble?`, ${me} ${c.qc_pebble} live`:`, ${me} absent`}\n${Object.entries(c.qc).map(([b,n])=>`${b} ${n}`).join(", ")}`}))
    :d.states.filter(s=>s.interest[bsel]!=null).map(s=>({l:s.state,lat:s.lat,lon:s.lon,v:s.interest[bsel],c:bsel===me?"var(--accent)":"var(--s2)",tip:`${s.state}: ${bsel} ${s.interest[bsel]}${s.field_interest!=null?` · field ${s.field_interest} · leader ${s.leader} ${s.leader_interest}`:""}`}));
  v.innerHTML=`<div class="xkpis">${N?"":kpi("own sales mapped",d.sales.total_revenue?inrS(d.sales.total_revenue):"none yet",`${d.sales.states_with_sales} states · ${d.days} days`)}${kpi("brands with search-interest data",d.stats.trend_brands,d.trends_period?`Google Trends · ${d.trends_period}`:"runs with the daily tier")}${kpi("cities with a Blinkit shelf read",d.stats.qc_cities,"quick commerce")}${N?"":kpi("gap states",d.gaps.length,"rivals out-index Pebble",d.gaps.length?"var(--s8)":"")}</div>
   <div class="grid gmap"><div class="card mapcard"><div class="row wrap maptools">${tabs(N?[["interest","search interest"],["qc","quick commerce"]]:[["interest","search interest"],["sales","own sales"],["qc","quick commerce"]],mode,"data-mode","inline")}${mode==="interest"?`<select id="rbrand" class="pillsel" aria-label="brand">${brands.map(b=>`<option ${b===bsel?"selected":""}>${esc(b)}</option>`).join("")}</select>`:""}</div>${pts.length?indiaMap(pts):'<div class="empty">'+(mode==="sales"?"Import sales on the Reports page (or set SHOPIFY_ADMIN_TOKEN) to see them by state.":mode==="qc"?"Blinkit shelves are read daily.":"Google Trends by state arrives with the daily tier (12 brands per run).")+'</div>'}<div class="legend">${mode==="interest"?"circle = search interest 0-100 (Google's scale, per brand)":mode==="sales"?"circle = revenue in the window":"circle = brands on the shelf · accent = Pebble present"}</div></div>
    <div style="display:grid;gap:16px;align-content:start">
     ${N?"":`<div class="card"><h2>Where rivals out-index ${esc(me)} <span class="hint">search interest, last 90 days</span></h2>${d.gaps.length?`<table><tr><th>State</th><th class="num">${esc(me)}</th><th class="num">Field</th><th>Leader</th><th class="num">Own sales share</th></tr>${d.gaps.map(g=>`<tr><td>${esc(g.state)}</td><td class="num">${g.pebble_interest}</td><td class="num">${g.field_interest}</td><td>${esc(g.leader||"")} <span class="muted small">${g.leader_interest||""}</span></td><td class="num">${g.sales_share_pct!=null?g.sales_share_pct+"%":"–"}</td></tr>`).join("")}</table>`:'<div class="empty">No gaps found (or no trends data yet).</div>'}</div>
     <div class="card"><h2>${esc(me)} strongholds</h2>${d.strongholds.length?d.strongholds.map(s=>chip(`${s.state} ${s.pebble_interest}`,"var(--accent)")).join(""):'<div class="empty">Needs Pebble\'s trends row.</div>'}</div>
     <div class="card"><h2>Own sales by state <span class="hint">${d.days} days</span></h2>${d.sales.top_states.length?hbars(d.sales.top_states.map(s=>({l:s.state,v:s.revenue,c:"var(--accent)"})),{fv:inrS}):'<div class="empty">No sales rows yet.</div>'}${d.sales.top_cities.length?`<div class="small muted" style="margin-top:8px">Cities: ${d.sales.top_cities.slice(0,8).map(c=>`${esc(c.city)} ${inrS(c.revenue)}`).join(" · ")}</div>`:""}</div>`}
     <div class="card"><h2>Brand reach <span class="hint">top states by search interest</span></h2><table><tr><th>Brand</th><th class="num">Mean</th><th>Top states</th></tr>${d.brands.slice(0,16).map(b=>`<tr><td>${esc(b.brand)}${b.self?' <span class="pill i0">you</span>':""}</td><td class="num">${b.national_mean}</td><td class="small">${b.top_states.map(s=>`${esc(s.state)} ${s.value}`).join(" · ")}</td></tr>`).join("")||'<tr><td colspan=3 class="muted">waiting for Google Trends</td></tr>'}</table></div>
    </div></div>`;
  v.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>{sessionStorage.setItem("regf",JSON.stringify({...F,mode:b.dataset.mode}));render();});const sel=$("#rbrand");if(sel)sel.onchange=()=>{sessionStorage.setItem("regf",JSON.stringify({...F,mode:"interest",brand:sel.value}));render();};};

/* ---------- Reports (sales + sector) ---------- */
X.vReports=async function(v){const F=JSON.parse(sessionStorage.getItem("repf")||"{}");const kind=F.kind||"weekly";const id=param();if(id&&/^\d+$/.test(id))return repOne(v,+id);
  head("Reports","daily · weekly · monthly · yearly performance and the sector report");
  const [sr,lst,ser]=await Promise.all([api(`/api/sales/report?kind=${kind==="sector"?"monthly":kind}&period=${F.period||""}`),api("/api/reports"),api(`/api/sales/series?kind=${kind==="sector"?"monthly":kind}&n=12`)]);const own=sr.own;const reps=lst.reports.filter(r=>r.kind===kind);
  v.innerHTML=`${tabs([["daily","Daily"],["weekly","Weekly"],["monthly","Monthly"],["yearly","Yearly"],["sector","Sector & industry"]],kind,"data-kind")}
   <div class="row wrap" style="margin-bottom:14px">${kind!=="sector"?`<select id="rper">${sr.periods.map(p=>`<option ${p===sr.period?"selected":""}>${p}</option>`).join("")}</select>`:""}<button class="primary" id="rbuild">Write ${kind} report${kind!=="sector"?" for "+esc(sr.period):""}</button><span class="muted small">${STATS.ai?"with an AI executive summary":"data-driven; add an AI key for the executive summary"}${lst.due.length?` · due now: ${lst.due.join(", ")}`:""}</span></div>
   ${kind!=="sector"?`<div class="xkpis">${NEUTRAL()?"":kpi("revenue",own.has_data?inrS(own.revenue):"–",own.has_data?`${pc(own.growth.revenue_pct)} vs previous`:"no own sales yet",own.has_data?col(own.growth.revenue_pct):"")+kpi("units",own.has_data?fmt(own.units):"–",own.has_data?pc(own.growth.units_pct):"")+kpi("orders",own.has_data?fmt(own.orders):"–",own.aov?`AOV ${inr(own.aov)}`:"")}${kpi("period",esc(sr.period),`${sr.start} → ${sr.end}`)}${kpi("rival proxies",sr.proxies.filter(p=>p.est_units).length,"brands with a sales proxy")}</div>
   <div class="grid g2">${NEUTRAL()?"":`<div class="card"><h2>Revenue trend <span class="hint">${kind} · own sales</span></h2>${ser.some(s=>s.revenue)?cols(ser.map(s=>({l:s.period,v:s.revenue,c:s.period===sr.period?"var(--accent)":"var(--s1)"})),{fv:inrS}):`<div class="empty">${esc(own.note||"No sales rows.")}</div>`}</div>`}
    <div class="card"><h2>Rivals' sales proxies <span class="hint">index 100 = strongest · reviews + ratings gained in the period</span></h2>${hbars(sr.proxies.filter(p=>p.est_units||p.self).slice(0,14).map(p=>({l:p.brand,v:p.index,c:p.self?"var(--accent)":"var(--s2)"})),{max:100})}<div class="small muted" style="margin-top:6px">units ≈ ratings gained ÷ ratings-per-100-units (config/channels.yaml → proxy). A relative gauge, not a count.</div></div>
    ${own.has_data?`<div class="card"><h2>By segment</h2><table><tr><th>Segment</th><th class="num">Revenue</th><th class="num">Units</th><th class="num">Growth</th></tr>${own.by_segment.map(s=>`<tr><td>${esc(s.key)}</td><td class="num">${inrS(s.revenue)}</td><td class="num">${fmt(s.units)}</td><td class="num" style="color:${col(s.growth_pct)}">${pc(s.growth_pct)}</td></tr>`).join("")}</table></div>
    <div class="card"><h2>By channel</h2>${hbars(own.by_channel.map(s=>({l:s.key,v:s.revenue,c:"var(--s3)"})),{fv:inrS})}</div>
    <div class="card"><h2>By state</h2>${hbars(own.by_state.slice(0,12).map(s=>({l:s.key,v:s.revenue,c:"var(--accent)"})),{fv:inrS})}</div>
    <div class="card"><h2>Top SKUs</h2><table><tr><th>SKU</th><th class="num">Revenue</th><th class="num">Units</th></tr>${own.top_skus.map(s=>`<tr><td>${esc(s.title||s.key)}<div class="small muted">${esc(s.key)}</div></td><td class="num">${inrS(s.revenue)}</td><td class="num">${fmt(s.units)}</td></tr>`).join("")}</table></div>`:""}
   </div>`:""}
   <div class="grid g2" style="margin-top:16px"><div class="card"><h2>Written ${kind} reports</h2>${reps.length?reps.map(r=>`<div style="padding:8px 0;border-bottom:1px solid var(--line)"><a href="#/reports/${r.id}"><b>${esc(r.title)}</b></a> <span class="muted small">${r.created_at.slice(0,16).replace("T"," ")}</span> · <a class="small" href="/api/reports/${r.id}.md">download .md</a></div>`).join(""):'<div class="empty">None written yet. Click "Write" above; the scheduler writes them automatically (daily 08:00, weekly on Monday, monthly / sector on the 1st, yearly on 1 January).</div>'}</div>
    ${NEUTRAL()?`<div class="card"><h2>Rivals only</h2><div class="small muted">This sector has no home brand, so there are no own sales to import; the reports read the market side only.</div></div>`:`<div class="card"><h2>Import Pebble sales <span class="hint">CSV: date, sku, title, channel, state, city, units, revenue</span></h2><div class="small ink2" style="margin-bottom:8px">Export orders from Shopify, Amazon Seller Central, Flipkart Seller Hub or your distributor sheet and drop the file here; column names are matched loosely. Re-importing is safe. Or set <code>SHOPIFY_ADMIN_TOKEN</code> in .env for an hourly pull. Sources so far: ${own.sources.length?own.sources.map(s=>chip(s)).join(""):"none"}</div><div class="row wrap"><input type="file" id="salesfile" accept=".csv,.tsv,.txt" style="max-width:100%;min-width:0;flex:1 1 220px"><input id="salessrc" placeholder="source label (amazon, offline…)" style="width:170px"><button id="salesgo">Import</button><a class="chip" href="/api/sales/template.csv">template.csv</a></div><div id="salesout" class="small muted" style="margin-top:8px"></div></div>`}</div>`;
  v.querySelectorAll("[data-kind]").forEach(b=>b.onclick=()=>{sessionStorage.setItem("repf",JSON.stringify({kind:b.dataset.kind}));render();});const per=$("#rper");if(per)per.onchange=()=>{sessionStorage.setItem("repf",JSON.stringify({kind,period:per.value}));render();};
  $("#rbuild").onclick=async()=>{toast("Writing the report… (up to a minute with AI)");try{const r=await post(`/api/reports/build?kind=${kind}&period=${kind==="sector"?"":encodeURIComponent(sr.period)}`);if(r.message)toast(r.message);if(r.id)location.hash="#/reports/"+r.id;else render();}catch(e){toast("Failed: "+e.message);}};
  if($("#salesgo"))$("#salesgo").onclick=async()=>{const f=$("#salesfile").files[0];if(!f){toast("Choose a CSV first");return;}const text=await f.text();try{const r=await post("/api/sales/import",{csv:text,source:$("#salessrc").value||f.name.replace(/\.\w+$/,"")});$("#salesout").textContent=`${r.added} rows imported (${r.skipped} skipped) · columns: ${Object.entries(r.columns).map(([k,v])=>`${k}←${v}`).join(", ")}${r.note?" · "+r.note:""} · refreshing…`;toast(`${r.added} sales rows imported`);setTimeout(render,4000);}catch(e){$("#salesout").textContent="Import failed: "+e.message;}};};
async function repOne(v,id){const r=await api("/api/reports/"+id);head(r.title,`<a href="#/reports">← reports</a> · written ${r.created_at.slice(0,16).replace("T"," ")} · <a href="/api/reports/${r.id}.md">download .md</a>`);v.innerHTML=`<div class="card xrep">${md(r.body)}</div>`;}

/* ---------- Strategy ---------- */
X.vStrategy=async function(v){head("Strategy","where to play, how to win, what to fix: scorecard, USP, problems, threats, 30/60/90 plan");const d=await api("/api/strategy");const VC={defend:"var(--good)",attack:"var(--s2)",enter:"var(--s7)",watch:"var(--muted)"};
  const before=`<div class="row wrap" style="margin-bottom:12px"><span class="muted small">computed ${ago(d.generated_at)} from the radar's data · every figure shows its basis on hover</span><span class="grow"></span><button class="sm" id="stref">Recompute</button>${STATS.ai?'<button class="sm primary" id="stmemo">Write AI strategy memo</button>':""}</div><div id="memo" class="card answer" style="display:none;margin-bottom:16px"></div>`;
  const score_=`<div class="card"><h2>Segment scorecard <span class="hint">attractiveness = size, growth, fragmentation · position = share, SKUs, price fit</span></h2><table><tr><th>Segment</th><th>Verdict</th><th class="num">Size ₹ cr</th><th class="num">Growth</th><th class="num">Share</th><th class="num">HHI</th><th class="num">Attractive</th><th class="num">Position</th><th>Why</th></tr>${d.scorecard.map(s=>`<tr><td><b>${esc(s.name)}</b><div class="small muted">${esc(s.leaders.join(", "))}</div></td><td><span class="pill" style="background:${VC[s.verdict]};color:#fff">${s.verdict}</span></td><td class="num">${fmt(s.value_cr)}</td><td class="num" style="color:${col(s.growth_pct)}">${pc(s.growth_pct)}</td><td class="num">${s.pebble_share_pct!=null?s.pebble_share_pct+"%":"–"}${s.pebble_rank?` <span class="small muted">#${s.pebble_rank}</span>`:""}</td><td class="num" data-tip="Herfindahl index of the shares: <1500 fragmented, >2500 concentrated">${s.hhi}</td><td class="num">${bar("",s.attractiveness,100,"var(--s1)",x=>x).replace('<span title=""></span>',"")}</td><td class="num">${bar("",s.position,100,"var(--accent)",x=>x).replace('<span title=""></span>',"")}</td><td class="small">${s.why.map(w=>`<div>${esc(w)}</div>`).join("")}</td></tr>`).join("")}</table><div class="small muted" style="margin-top:6px">sizes and shares from config/market.yaml (${d.scorecard[0]&&d.scorecard[0].confidence||"estimate"}); price gap, SKUs and white space from the live catalogues.</div></div>
`;
  const usp_=`<div class="grid g2">
    <div class="card"><h2>USP: what Pebble can own</h2>${d.usp.claims.map(c=>`<div class="xcl"><div><span class="pill i0">${c.kind}</span> <b>${esc(c.claim)}</b></div>${c.quote?`<div class="xq neg small">“${esc(c.quote.text)}” <span class="muted">— ${esc(c.quote.brand||"")} ${esc(c.quote.source||"")}</span></div>`:""}<div class="small muted">${esc(c.basis)}${c.field_neg_pct!=null?` · field ${c.field_neg_pct}% vs Pebble ${c.pebble_neg_pct==null?"n/a":c.pebble_neg_pct+"%"}`:""}</div></div>`).join("")||'<div class="empty">Needs reviews and comments (daily tier) to find claims.</div>'}</div>
    <div class="card"><h2>Fix first <span class="hint">by severity</span></h2>${d.problems.map(p=>`<div class="xcl"><div>${pill(p.severity)} <span class="chip">${esc(p.area)}</span> <b>${esc(p.problem)}</b></div><div class="small ink2" style="padding-left:10px;border-left:2px solid var(--s3)">${esc(p.fix)}</div>${p.quote?`<div class="xq neg small">“${esc(p.quote.text)}”</div>`:""}<div class="small muted">${esc(p.basis)}</div></div>`).join("")||'<div class="empty">Nothing flagged.</div>'}</div>
</div>`;
  const threats_=`<div class="grid g2"><div class="card"><h2>Threats</h2>${d.threats.map(t=>`<div class="small" style="padding:5px 0;border-bottom:1px solid var(--line)">${pill(t.importance)} <b>${esc(t.brand)}</b> ${esc(t.title)}${t.why?`<div class="muted">${esc(t.why)}</div>`:""}</div>`).join("")||'<div class="empty">None open.</div>'}${d.pressure?`<div class="small muted" style="margin-top:8px">pressure model: ≈ ${inrS(d.pressure.total_risk)}/month at risk · ≈ ${inrS(d.pressure.total_upside)}/month upside</div>`:""}</div>
    <div class="card"><h2>Opportunities</h2>${d.opportunities.map(t=>`<div class="small" style="padding:5px 0;border-bottom:1px solid var(--line)">${pill(t.importance)} <b>${esc(t.brand)}</b> ${esc(t.title)}${t.why?`<div class="muted">${esc(t.why)}</div>`:""}</div>`).join("")||'<div class="empty">None open.</div>'}</div>
</div>`;
  const plan_=`<div class="grid" style="grid-template-columns:1fr"><div class="card"><h2>SWOT</h2><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))">${[["Strengths","strengths","var(--good)"],["Weaknesses","weaknesses","var(--s8)"],["Opportunities","opportunities","var(--s1)"],["Threats","threats","var(--s2)"]].map(([l,k,c])=>`<div><h3 style="color:${c}">${l}</h3><ul class="small" style="padding-left:18px;margin:6px 0">${(d.swot[k]||[]).map(x=>`<li>${esc(x)}</li>`).join("")||"<li class='muted'>–</li>"}</ul></div>`).join("")}</div></div>
    <div class="card"><h2>30 / 60 / 90-day plan</h2><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))">${["30","60","90"].map(h=>`<div><h3>Next ${h} days</h3><ol class="small" style="padding-left:18px;margin:6px 0">${(d.plan[h]||[]).map(x=>`<li style="margin:4px 0">${esc(x)}</li>`).join("")}</ol></div>`).join("")}</div></div>
   </div>`;
  tabbed(v,[{key:"scorecard",label:"Segment scorecard",html:score_},{key:"usp",label:"USP & fixes",html:usp_,count:(d.problems||[]).length||null},{key:"threats",label:"Threats & opportunities",html:threats_,count:((d.threats||[]).length+(d.opportunities||[]).length)||null},{key:"plan",label:"SWOT & plan",html:plan_}],{before});
  $("#stref").onclick=async()=>{toast("Recomputing…");await api("/api/strategy?refresh=1");render();};const m=$("#stmemo");if(m)m.onclick=async()=>{const box=$("#memo");box.style.display="";box.textContent="Writing…";const r=await post("/api/strategy/memo");box.textContent=r.text||r.message||"No answer.";};};

/* Yahoo fundamentals, when the daily tier has them for a listed company */
X.fundChips=function(f){if(!f)return"";const pc1=v=>v==null?null:(Math.abs(v)<=1.5?v*100:v);const cap=f.market_cap!=null?(f.currency==="INR"?inrS(f.market_cap):(f.currency==="USD"?"$":f.currency+" ")+(f.market_cap>=1e9?(f.market_cap/1e9).toFixed(1)+" B":(f.market_cap/1e6).toFixed(0)+" M")):null;
  const items=[cap&&["market cap",cap],f.trailing_pe!=null&&["P/E",Number(f.trailing_pe).toFixed(1)],f.forward_pe!=null&&["fwd P/E",Number(f.forward_pe).toFixed(1)],f.revenue_growth!=null&&["revenue growth",pc(pc1(f.revenue_growth))],f.gross_margin!=null&&["gross margin",pc(pc1(f.gross_margin)).replace("+","")],f.operating_margin!=null&&["operating margin",pc(pc1(f.operating_margin)).replace("+","")],f.profit_margin!=null&&["net margin",pc(pc1(f.profit_margin)).replace("+","")],f.dividend_yield!=null&&["dividend",pc(pc1(f.dividend_yield)).replace("+","")],f.analyst_rating&&["analysts",String(f.analyst_rating).replace(/_/g," ")]].filter(Boolean);
  return items.length?`<div class="row wrap small" style="margin:6px 0 2px;gap:6px">${items.map(([l,v])=>`<span class="chip"><span class="muted">${esc(l)}</span> <b>${esc(v)}</b></span>`).join("")}${f.most_recent_quarter?`<span class="muted xs">Yahoo Finance · ${esc(f.most_recent_quarter)}</span>`:""}</div>`:"";};
/* ---------- styles + registration ---------- */
const css=document.createElement("style");css.textContent=`@media(max-width:860px){.grid[style*="minmax(0,520px)"]{grid-template-columns:1fr!important}}`;document.head.appendChild(css);
document.addEventListener("click",e=>{const g=e.target.closest("[data-go]");if(g)location.hash=g.dataset.go;});
X.brandChannels=function(d){const s=d.shelf;if(!s||!s.channels||!s.channels.length)return`<div class="card"><div class="empty">No marketplace or quick-commerce listing for ${esc(d.brand)} yet. Amazon.in and Flipkart are read every 6 h, Blinkit city by city daily; retail chains are picked up from news mentions.</div>${(s&&s.mentions&&s.mentions.length)?`<h2 style="margin-top:12px">Reported in</h2>${s.mentions.map(m=>`<div class="small"><a href="${esc(m.url||"#")}" target="_blank" rel="noopener">${esc(m.title)}</a> <span class="muted">${esc(m.channel)} · ${esc((m.seen_at||"").slice(0,10))}</span></div>`).join("")}`:""}</div>`;
  const rows=c=>c.listings.slice(0,40).map(l=>{const first=l.first_price,mv=first&&l.price&&first!==l.price?Math.round((l.price-first)/first*100):0;return`<tr><td>${l.url?`<a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.title.slice(0,70))}</a>`:esc(l.title.slice(0,70))}${l.sponsored?' <span class="chip">ad</span>':""}</td>${c.key==="blinkit"?`<td class="muted">${esc(l.city||"")}</td>`:""}<td class="num">${l.price?inr(l.price):"–"}${l.mrp&&l.mrp>l.price?` <s class="muted small">${inr(l.mrp)}</s>`:""}${mv?` <span class="small" style="color:${mv<0?"var(--good)":"var(--s8)"}">${mv>0?"+":""}${mv}%</span>`:""}</td><td class="num">${l.rating?`${l.rating} ★`:"–"}${l.rating_count?` <span class="muted small">${fmt(l.rating_count)}</span>`:""}</td><td>${l.available?"in stock":'<span style="color:var(--s8)">out</span>'}</td></tr>`;}).join("");
  const parity=(s.parity||[]).slice(0,12);
  return`<div class="grid g2">${s.channels.map(c=>`<div class="card"${c.key==="blinkit"?' style="grid-column:1/-1"':""}><h2>${esc(c.name||c.key)} <span class="hint">${c.listings.length} listing${c.listings.length>1?"s":""}${c.key==="blinkit"?" across cities":""}</span></h2><table><tr><th>Listing</th>${c.key==="blinkit"?"<th>City</th>":""}<th class="num">Price</th><th class="num">Rating</th><th>Stock</th></tr>${rows(c)}</table></div>`).join("")}
   ${parity.length?`<div class="card" style="grid-column:1/-1"><h2>Marketplace vs own store <span class="hint">same SKU matched to the brand's D2C price</span></h2><table><tr><th>Listing</th><th>Channel</th><th class="num">Marketplace</th><th class="num">Own store</th><th class="num">Gap</th></tr>${parity.map(p=>`<tr><td><a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title.slice(0,60))}</a></td><td class="muted">${esc(p.channel)}</td><td class="num">${inr(p.marketplace_price)}</td><td class="num">${p.store_url?`<a href="${esc(p.store_url)}" target="_blank" rel="noopener">${inr(p.store_price)}</a>`:inr(p.store_price)}</td><td class="num" style="color:${p.gap_pct<0?"var(--s8)":"var(--good)"}">${p.gap_pct>0?"+":""}${p.gap_pct}%</td></tr>`).join("")}</table></div>`:""}
   ${(s.events||[]).length?`<div class="card" style="grid-column:1/-1"><h2>Shelf changes</h2>${s.events.slice(0,20).map(e=>`<div class="small" style="padding:4px 0;border-bottom:1px solid var(--line)"><span class="pill i${Math.min(9,e.importance||4)}">${e.importance||4}</span> ${esc(e.title)} <span class="muted">${esc((e.created_at||"").slice(0,10))}</span></div>`).join("")}</div>`:""}
   ${(s.mentions||[]).length?`<div class="card" style="grid-column:1/-1"><h2>Reported in <span class="hint">retail and q-commerce channels named in the news</span></h2>${s.mentions.map(m=>`<div class="small"><a href="${esc(m.url||"#")}" target="_blank" rel="noopener">${esc(m.title)}</a> <span class="muted">${esc(m.channel)} · ${esc((m.seen_at||"").slice(0,10))}</span></div>`).join("")}</div>`:""}</div>`;};
X.brandRegions=function(d){const r=d.regions;if(!r||(!r.states.length&&!r.qc.length&&!r.mentions.length))return`<div class="card"><div class="empty">No regional signal for ${esc(d.brand)} yet. Google Trends by state is refreshed weekly per brand; Blinkit shelves per city daily.</div></div>`;
  const mx=Math.max(1,...r.states.map(s=>s.value));
  return`<div class="grid g2"><div class="card"><h2>Search interest by state <span class="hint">Google Trends ${esc(r.period||"")} · ${esc((r.states[0]||{}).detail||"")}</span></h2>${r.states.length?r.states.map(s=>`<div class="bar"><span>${esc(s.region)}</span><div class="tr"><div class="f" style="width:${s.value/mx*100}%;background:var(--accent)"></div></div><span class="v">${Math.round(s.value)}</span></div>`).join(""):'<div class="empty">Not read yet this week.</div>'}</div>
   <div class="card"><h2>Quick-commerce shelves by city <span class="hint">Blinkit, last 7 days</span></h2>${r.qc.length?`<table><tr><th>City</th><th class="num">Listed</th><th class="num">In stock</th><th class="num">From</th></tr>${r.qc.map(c=>`<tr><td>${esc(c.city)}</td><td class="num">${c.n}</td><td class="num">${c.a||0}</td><td class="num">${c.p?inr(c.p):"–"}</td></tr>`).join("")}</table>`:'<div class="empty">Not on Blinkit in any tracked city.</div>'}
   ${r.mentions.length?`<h2 style="margin-top:12px">Places named in coverage</h2>${r.mentions.map(m=>`<div class="small">${esc(m.region)} <span class="muted">${esc(m.level)} · ${m.value} mention${m.value>1?"s":""}</span></div>`).join("")}`:""}</div>
   <div class="card" style="grid-column:1/-1"><a href="#/regions">Open the Regions map for every brand →</a></div></div>`;};
X.parityCard=function(par){if(!par||!par.length)return"";const mine=par.filter(p=>p.self),under=mine.filter(p=>p.gap_pct<=-8),rivals=par.filter(p=>!p.self&&p.gap_pct<=-8).slice(0,6);
  return`<div class="card"${under.length?' style="border-color:var(--s8)"':""}><h2>Marketplace vs own store <span class="hint">live listings matched to D2C catalogue prices · <a href="#/channels">Channels</a></span></h2>
   ${mine.length?`<table><tr><th>Pebble SKU</th><th>Channel</th><th class="num">Marketplace</th><th class="num">pebblecart</th><th class="num">Gap</th></tr>${mine.slice(0,10).map(p=>`<tr><td><a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title.slice(0,60))}</a></td><td class="muted">${esc(p.channel)}${p.city?" · "+esc(p.city):""}</td><td class="num">${inr(p.marketplace_price)}</td><td class="num">${inr(p.store_price)}</td><td class="num" style="color:${p.gap_pct<0?"var(--s8)":"var(--good)"}">${p.gap_pct>0?"+":""}${p.gap_pct}%</td></tr>`).join("")}</table>`:'<div class="small muted">No Pebble SKU matched on a marketplace yet.</div>'}
   ${rivals.length?`<div class="hint" style="margin-top:10px">Rivals selling below their own store (where their buyers go)</div>${rivals.map(p=>`<div class="small">${esc(p.brand)}: ${esc(p.title.slice(0,50))} <span class="muted">${esc(p.channel)} ${inr(p.marketplace_price)} vs store ${inr(p.store_price)}</span> <span style="color:var(--s8)">${p.gap_pct}%</span></div>`).join("")}`:""}</div>`;};
Object.assign(window,X);
})();
